import sys
import math

def floyd_warshall(n, edges):
    dist = [[math.inf] * n for _ in range(n)]
    for i in range(n):
        dist[i][i] = 0
    for u, v, w in edges:
        dist[u-1][v-1] = w
        dist[v-1][u-1] = w
    for k in range(n):
        for i in range(n):
            for j in range(n):
                if dist[i][k] + dist[k][j] < dist[i][j]:
                    dist[i][j] = dist[i][k] + dist[k][j]
    return dist

def min_time_to_deliver_candies(n, m, candies):
    edges = []
    for i in range(1, n+1):
        edges.append((i, i % n + 1, 1))
    dist = floyd_warshall(n, edges)
    result = []
    for start in range(1, n+1):
        total_time = 0
        for a, b in candies:
            total_time += dist[start-1][a-1] + dist[a-1][b-1]
        result.append(total_time)
    return result

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    index = 0
    n = int(data[index])
    m = int(data[index + 1])
    index += 2

    candies = []
    for _ in range(m):
        a = int(data[index])
        b = int(data[index + 1])
        candies.append((a, b))
        index += 2

    result = min_time_to_deliver_candies(n, m, candies)
    print(" ".join(map(str, result)))

if __name__ == "__main__":
    main()
